def transform(grid):
    """Tile 8-cells with 2x2 squares and L triominoes; color by tile type."""
    cells = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 8}
    placements = []
    h, w = len(grid), len(grid[0]) if grid else 0
    for r in range(h - 1):
        for c in range(w - 1):
            corners = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            square = set(corners)
            if square <= cells:
                placements.append((square, 1))
            # L-triomino color is determined by the missing corner.
            for missing, color in ((0, 2), (2, 3), (1, 4), (3, 5)):
                shape = square - {corners[missing]}
                if shape <= cells:
                    placements.append((shape, color))
    by_cell = {cell: [] for cell in cells}
    for shape, color in placements:
        for cell in shape:
            by_cell[cell].append((shape, color))

    def cover(remaining):
        if not remaining:
            return []
        cell = min(remaining, key=lambda x: sum(shape <= remaining for shape, _ in by_cell[x]))
        for shape, color in by_cell[cell]:
            if shape <= remaining:
                rest = cover(remaining - shape)
                if rest is not None:
                    return [(shape, color)] + rest
        return None

    tiling = cover(cells)
    if tiling is None:
        return [row[:] for row in grid]
    out = [[0] * w for _ in range(h)]
    for shape, color in tiling:
        for r, c in shape:
            out[r][c] = color
    return out
